18	package org.keycloak.common.util;
19	
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Map;
24	import java.util.Optional;
25	
26	public interface MultivaluedMap<K, V> extends Map<K, List<V>> {
27	
28	    public default void putSingle(K key, V value) {
29	        List<V> list = createListInstance();
30	        list.add(value);
31	        put(key, list); // Just override with new List instance
32	    }
33	
34	    public default void addAll(K key, V... newValues) {
35	        for (V value : newValues) {
36	            add(key, value);
37	        }
38	    }
39	
40	    public default void addAll(K key, List<V> valueList) {
41	        for (V value : valueList) {
42	            add(key, value);
43	        }
44	    }
45	
46	    public default void addFirst(K key, V value) {
47	        getList(key).add(0, value);
48	    }
49	
50	    public default void add(K key, V value) {
51	        getList(key).add(value);
52	    }
53	
54	    public default void addMultiple(K key, Collection<V> values) {
55	        getList(key).addAll(values);
56	    }
57	
58	    public default V getFirst(K key) {
59	        return Optional.ofNullable(get(key)).filter(l -> !l.isEmpty()).map(l -> l.get(0)).orElse(null);
60	    }
61	
62	    default V getFirstOrDefault(K key, V defaultValue) {
63	        return Optional.ofNullable(getFirst(key)).orElse(defaultValue);
64	    }
65	
66	    public default List<V> getList(K key) {
67	        return compute(key, (k, v) -> v != null ? v : createListInstance());
68	    }
69	
70	    public default void addAll(MultivaluedMap<K, V> other) {
71	        for (Entry<K, List<V>> entry : other.entrySet()) {
72	            getList(entry.getKey()).addAll(entry.getValue());
73	        }
74	    }
75	
76	    public default boolean equalsIgnoreValueOrder(MultivaluedMap<K, V> omap) {
77	       if (this == omap) {
78	          return true;
79	       }
80	       if (!keySet().equals(omap.keySet())) {
81	          return false;
82	       }
83	       for (Map.Entry<K, List<V>> e : entrySet()) {
84	           List<V> list = e.getValue();
85	           List<V> olist = omap.get(e.getKey());
86	           if (!CollectionUtil.collectionEquals(list, olist)) {
87	               return false;
88	           }
89	       }
90	       return true;
91	    }
92	
93	    public default List<V> createListInstance() {
94	        return new ArrayList<>();
95	    }
96	
97	}
