18	package org.keycloak.common.util;
19	
20	import java.util.List;
21	import java.util.Map;
22	import java.util.concurrent.ConcurrentHashMap;
23	import java.util.concurrent.CopyOnWriteArrayList;
24	
25	/**
26	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
27	 * @version $Revision: 1 $
28	 */
29	@SuppressWarnings("serial")
30	public class ConcurrentMultivaluedHashMap<K, V> extends ConcurrentHashMap<K, List<V>> implements MultivaluedMap<K, V>
31	{
32	    public ConcurrentMultivaluedHashMap() {
33	    }
34	
35	    public ConcurrentMultivaluedHashMap(Map<K, List<V>> map) {
36	        if (map == null) {
37	            throw new IllegalArgumentException("Map can not be null");
38	        }
39	        putAll(map);
40	    }
41	
42	   @Override
43	   public List<V> createListInstance() {
44	      return new CopyOnWriteArrayList<>();
45	   }
46	
47	}
