18	package org.keycloak.common.util;
19	
20	import java.util.regex.Matcher;
21	import java.util.regex.Pattern;
22	
23	/**
24	 * Replaces any ${} strings with their corresponding system property.
25	 *
26	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
27	 * @version $Revision: 1 $
28	 */
29	public final class EnvUtil {
30	    private static final Pattern p = Pattern.compile("[$][{]([^}]+)[}]");
31	
32	    private EnvUtil() {
33	
34	    }
35	
36	    /**
37	     * Replaces any ${} strings with their corresponding system property.
38	     *
39	     * @param val
40	     * @return
41	     */
42	    public static String replace(String val) {
43	        Matcher matcher = p.matcher(val);
44	        StringBuffer buf = new StringBuffer();
45	        while (matcher.find()) {
46	            String envVar = matcher.group(1);
47	            String envVal = System.getProperty(envVar);
48	            if (envVal == null) envVal = "NOT-SPECIFIED";
49	            matcher.appendReplacement(buf, Matcher.quoteReplacement(envVal));
50	        }
51	        matcher.appendTail(buf);
52	        return buf.toString();
53	    }
54	}
