1	package org.keycloak.common.util;
2	
3	import java.util.concurrent.ConcurrentHashMap;
4	import java.util.regex.Pattern;
5	
6	import org.jboss.logging.Logger;
7	
8	/**
9	 *
10	 * @author hmlnarik
11	 */
12	public class StackUtil {
13	
14	    private static final Logger LOG = Logger.getLogger("org.keycloak.STACK_TRACE");
15	
16	    private static final ConcurrentHashMap<String, Object> STACK_TRACE_OBJECTS = new ConcurrentHashMap<>();
17	
18	    /**
19	     * Returns string representation of the stack trace of the current call
20	     * without the call to the {@code getShortStackTrace} itself, and ignoring
21	     * usually irrelevant calls to methods in {@code sun.} and {@code java.lang.reflect}
22	     * packages. The stack trace ignores calls before and including the first
23	     * {@code org.jboss.resteasy} method, hence it usually finishes with the
24	     * method handling respective REST endpoint.
25	     *
26	     * Each line of the stack trace is prepended with {@code "\n    "}.
27	     *
28	     * @return If the logger {@code org.keycloak.STACK_TRACE} is set to trace
29	     * level, then returns stack trace, else returns empty {@link StringBuilder}
30	     */
31	    public static Object getShortStackTrace() {
32	        return getShortStackTrace("\n    ");
33	    }
34	
35	    private static final Pattern IGNORED = Pattern.compile("sun\\.|"
36	      + "java\\.(lang|util|stream)\\.|"
37	      + "jdk\\.internal\\.|"
38	      + "org\\.jboss\\.(arquillian|logging|logmanager|threads).|"
39	      + "org.apache.maven.surefire|"
40	      + "org\\.xnio\\.|"
41	      + "org\\.junit\\.|"
42	      + "org\\.infinispan\\.(interceptors|cache|notifications\\.cachelistener)\\.|"
43	      + "io\\.quarkus\\.|"
44	      + "io\\.undertow\\.|"
45	      + "picocli\\.|"
46	      + "org.keycloak.testsuite.model.KeycloakModelTest\\."
47	    );
48	    private static final StringBuilder EMPTY = new StringBuilder(0);
49	
50	    /**
51	     * Returns string representation of the stack trace of the current call
52	     * without the call to the {@code getShortStackTrace} itself, and ignoring
53	     * usually irrelevant calls to methods in {@code sun.} and {@code java.lang.reflect}
54	     * packages. The stack trace ignores calls before and including the first
55	     * {@code org.jboss.resteasy} method, hence it usually finishes with the
56	     * method handling respective REST endpoint.
57	     *
58	     * @param prefix Prefix to prepend to every stack trace line
59	     * @return If the logger {@code org.keycloak.STACK_TRACE} is set to trace
60	     * level, then returns stack trace, else returns empty {@link StringBuilder}
61	     */
62	    public static Object getShortStackTrace(final String prefix) {
63	        if (! isShortStackTraceEnabled()) return EMPTY;
64	
65	        Object res = STACK_TRACE_OBJECTS.get(prefix);
66	        if (res == null) {
67	            res = stackTraceObject(prefix);
68	            // Do not synchronize. We don't care if the objects in the map get overridden, they are in the end the same.
69	            STACK_TRACE_OBJECTS.put(prefix, res);
70	        }
71	        return res;
72	    }
73	
74	    private static Object stackTraceObject(final String prefix) {
75	        return new Object() {
76	            @Override
77	            public String toString() {
78	                StringBuilder sb = new StringBuilder();
79	                StackTraceElement[] stackTrace = (new Throwable()).getStackTrace();
80	                boolean stackTraceStarted = false;
81	                for (int endIndex = 0; endIndex < stackTrace.length; endIndex++) {
82	                    StackTraceElement st = stackTrace[endIndex];
83	                    if (! stackTraceStarted) {
84	                        stackTraceStarted = (getClass().getName().equals(st.getClassName()));
85	                        endIndex++;
86	                        continue;
87	                    }
88	                    if (IGNORED.matcher(st.getClassName()).find()) {
89	                        continue;
90	                    }
91	                    if (st.getClassName().startsWith("org.jboss.resteasy")) {
92	                        break;
93	                    }
94	                    sb.append(prefix).append(st);
95	                }
96	                return sb.toString();
97	            }
98	        };
99	    }
100	
101	    public static boolean isShortStackTraceEnabled() {
102	        return LOG.isTraceEnabled();
103	    }
104	}
