1	package org.keycloak.common.util;
2	
3	import java.time.Duration;
4	import java.time.format.DateTimeParseException;
5	import java.util.regex.Pattern;
6	
7	public class DurationConverter {
8	
9	    private static final String PERIOD = "P";
10	    private static final String PERIOD_OF_TIME = "PT";
11	    public static final Pattern DIGITS = Pattern.compile("^[-+]?\\d+$");
12	    private static final Pattern DIGITS_AND_UNIT = Pattern.compile("^(?:[-+]?\\d+(?:\\.\\d+)?(?i)[hms])+$");
13	    private static final Pattern DAYS = Pattern.compile("^[-+]?\\d+(?i)d$");
14	    private static final Pattern MILLIS = Pattern.compile("^[-+]?\\d+(?i)ms$");
15	
16	    /**
17	     * If the {@code value} starts with a number, then:
18	     * <ul>
19	     * <li>If the value is only a number, it is treated as a number of seconds.</li>
20	     * <li>If the value is a number followed by {@code ms}, it is treated as a number of milliseconds.</li>
21	     * <li>If the value is a number followed by {@code h}, {@code m}, or {@code s}, it is prefixed with {@code PT}
22	     * and {@link Duration#parse(CharSequence)} is called.</li>
23	     * <li>If the value is a number followed by {@code d}, it is prefixed with {@code P}
24	     * and {@link Duration#parse(CharSequence)} is called.</li>
25	     * </ul>
26	     *
27	     * Otherwise, {@link Duration#parse(CharSequence)} is called.
28	     *
29	     * @param value a string duration
30	     * @return the parsed {@link Duration}
31	     * @throws IllegalArgumentException in case of parse failure
32	     */
33	    public static Duration parseDuration(String value) {
34	        if (value == null || value.trim().isEmpty()) {
35	            return null;
36	        }
37	        if (DIGITS.asPredicate().test(value)) {
38	            return Duration.ofSeconds(Long.parseLong(value));
39	        } else if (MILLIS.asPredicate().test(value)) {
40	            return Duration.ofMillis(Long.parseLong(value.substring(0, value.length() - 2)));
41	        }
42	
43	        try {
44	            if (DIGITS_AND_UNIT.asPredicate().test(value)) {
45	                return Duration.parse(PERIOD_OF_TIME + value);
46	            } else if (DAYS.asPredicate().test(value)) {
47	                return Duration.parse(PERIOD + value);
48	            }
49	
50	            return Duration.parse(value);
51	        } catch (DateTimeParseException e) {
52	            throw new IllegalArgumentException(e);
53	        }
54	    }
55	
56	    /**
57	     * Checks whether the given value represents a positive duration.
58	     *
59	     * @param value a string duration following the same format as in {@link #parseDuration(String)}
60	     * @return true if the value represents a positive duration, false otherwise
61	     */
62	    public static boolean isPositiveDuration(String value) {
63	        Duration duration = parseDuration(value);
64	        return duration != null && !duration.isNegative() && !duration.isZero();
65	    }
66	}
