3	import java.util.Map;
4	import java.util.concurrent.ConcurrentHashMap;
5	
6	import org.keycloak.representations.AuthorizationDetailsJSONRepresentation;
7	
8	/**
9	 * Parser, which is able to create specific subtype of {@link AuthorizationDetailsJSONRepresentation} in performant way
10	 */
11	public interface AuthorizationDetailsParser {
12	
13	    <T extends AuthorizationDetailsJSONRepresentation> T asSubtype(AuthorizationDetailsJSONRepresentation authzDetail, Class<T> clazz);
14	
15	
16	    Map<String, AuthorizationDetailsParser> PARSERS = new ConcurrentHashMap<>();
17	
18	    /**
19	     * Register new parser for specific type. This can be later used by {@link #asSubtype} method. Parsers are supposed to be
20	     * registered before authorizationDetails are being used by the application and before method {@link #asSubtype} is called for the first time.
21	     * Usually it is supposed to be registered at the startup of the application. If implementing Keycloak provider <em>AuthorizationDetailsProcessor</em>, it might
22	     * be good to register corresponding parser in the <em>AuthorizationDetailsProcessorFactory.init</em> method of your provider
23	     *
24	     * @param type Type as used in the "type" claim of "authorization_details" object entry
25	     * @param parser Parser for this type
26	     */
27	    static void registerParser(String type, AuthorizationDetailsParser parser) {
28	        PARSERS.put(type, parser);
29	    }
30	
31	    /**
32	     * Method is not supposed to be called directly. Rather please make sure to use {@link #registerParser(String, AuthorizationDetailsParser)} and
33	     * then use {@link #asSubtype(AuthorizationDetailsJSONRepresentation, Class)} to call directly from the application
34	     *
35	     * @param authzDetail Authorization detail object to cast
36	     * @param clazz Subtype of {@link AuthorizationDetailsJSONRepresentation}, which will be returned by calling this method
37	     * @return given authzDetail passed in <em>authzDetail</em> parameter cast to the class specified by clazz parameter as long as parser corresponding to the type
38	     * returned by {@link AuthorizationDetailsJSONRepresentation#getType} is able to parse this authorizationDetails and convert it to that subtype
39	     */
40	    static <T extends AuthorizationDetailsJSONRepresentation> T parseToSubtype(AuthorizationDetailsJSONRepresentation authzDetail, Class<T> clazz) {
41	        if (authzDetail.getType() == null) {
42	            throw new IllegalArgumentException("Used authzDetail entry does not have 'type' set. The used authzDetail entry was: " + authzDetail);
43	        }
44	        AuthorizationDetailsParser parser = PARSERS.get(authzDetail.getType());
45	        if (parser == null) {
46	            throw new IllegalArgumentException("Unsupported to parse response of type '" + authzDetail.getType() + "' to the class '" + clazz +
47	                    "'. Please make sure that corresponding parser is registered.");
48	        }
49	        return parser.asSubtype(authzDetail, clazz);
50	    }
51	}
