50	    private static final Logger LOG = Logger.getLogger(TokenVerifier.class.getName());
51	
52	    // This interface is here as JDK 7 is a requirement for this project.
53	    // Once JDK 8 would become mandatory, java.util.function.Predicate would be used instead.
54	
55	    /**
56	     * Functional interface of checks that verify some part of a JWT.
57	     * @param <T> Type of the token handled by this predicate.
58	     */
59	    // @FunctionalInterface
60	    public static interface Predicate<T extends JsonWebToken> {
61	        /**
62	         * Performs a single check on the given token verifier.
63	         * @param t Token, guaranteed to be non-null.
64	         * @return
65	         * @throws VerificationException
66	         */
67	        boolean test(T t) throws VerificationException;
68	    }
