70	    public static final Predicate<JsonWebToken> SUBJECT_EXISTS_CHECK = new Predicate<JsonWebToken>() {
71	        @Override
72	        public boolean test(JsonWebToken t) throws VerificationException {
73	            String subject = t.getSubject();
74	            if (subject == null) {
75	                throw new VerificationException("Subject missing in token");
76	            }
77	
78	            return true;
79	        }
80	    };
81	
82	    /**
83	     * Check for token being neither expired nor used before it gets valid.
84	     * @see JsonWebToken#isActive()
85	     */
86	    public static final Predicate<JsonWebToken> IS_ACTIVE = new Predicate<JsonWebToken>() {
87	        @Override
88	        public boolean test(JsonWebToken t) throws VerificationException {
89	            if (! t.isActive()) {
90	                throw new TokenNotActiveException(t, "Token is not active");
91	            }
92	
93	            return true;
94	        }
95	    };
