97	    public static class RealmUrlCheck implements Predicate<JsonWebToken> {
98	
99	        private static final RealmUrlCheck NULL_INSTANCE = new RealmUrlCheck(null);
100	
101	        private final String realmUrl;
102	
103	        public RealmUrlCheck(String realmUrl) {
104	            this.realmUrl = realmUrl;
105	        }
106	
107	        @Override
108	        public boolean test(JsonWebToken t) throws VerificationException {
109	            if (this.realmUrl == null) {
110	                throw new VerificationException("Realm URL not set");
111	            }
112	
113	            if (! this.realmUrl.equals(t.getIssuer())) {
114	                throw new VerificationException("Invalid token issuer. Expected '" + this.realmUrl + "'");
