249	     * <ul>
250	     * <li>Realm URL (JWT issuer field: {@code iss}) has to be defined and match realm set via {@link #realmUrl(java.lang.String)} method</li>
251	     * <li>Subject (JWT subject field: {@code sub}) has to be defined</li>
252	     * <li>Token type (JWT type field: {@code typ}) has to be {@code Bearer}. The type can be set via {@link #tokenType(List)} method</li>
253	     * <li>Token has to be active, ie. both not expired and not used before its validity (JWT issuer fields: {@code exp} and {@code nbf})</li>
254	     * </ul>
255	     * @return This token verifier.
256	     */
257	    public TokenVerifier<T> withDefaultChecks()  {
258	        return withChecks(
259	          RealmUrlCheck.NULL_INSTANCE,
260	          TokenTypeCheck.INSTANCE_DEFAULT_TOKEN_TYPE,
261	          IS_ACTIVE
262	        );
263	    }
264	
265	    private void removeCheck(Class<? extends Predicate<?>> checkClass) {
266	        for (Iterator<Predicate<? super T>> it = checks.iterator(); it.hasNext();) {
267	            if (it.next().getClass() == checkClass) {
268	                it.remove();
269	            }
270	        }
271	    }
272	
273	    private void removeCheck(Predicate<? super T> check) {
274	        checks.remove(check);
275	    }
276	
277	    @SuppressWarnings("unchecked")
278	    private <P extends Predicate<? super T>> TokenVerifier<T> replaceCheck(Class<? extends Predicate<?>> checkClass, boolean active, P... predicate) {
279	        removeCheck(checkClass);
280	        if (active) {
281	            checks.addAll(Arrays.asList(predicate));
282	        }
283	        return this;
284	    }
285	
286	    @SuppressWarnings("unchecked")
287	    private <P extends Predicate<? super T>> TokenVerifier<T> replaceCheck(Predicate<? super T> check, boolean active, P... predicate) {
288	        removeCheck(check);
289	        if (active) {
290	            checks.addAll(Arrays.asList(predicate));
291	        }
292	        return this;
293	    }
