399	    public TokenVerifier<T> parse() throws VerificationException {
400	        if (jws == null) {
401	            if (tokenString == null) {
402	                throw new VerificationException("Token not set");
403	            }
404	
405	            try {
406	                jws = new JWSInput(tokenString);
407	            } catch (JWSInputException e) {
408	                throw new VerificationException("Failed to parse JWT", e);
409	            }
410	
411	
412	            try {
413	                token = jws.readJsonContent(clazz);
414	            } catch (JWSInputException e) {
415	                throw new VerificationException("Failed to read access token from JWT", e);
416	            }
417	        }
418	        return this;
419	    }
420	
421	    public T getToken() throws VerificationException {
422	        if (token == null) {
423	            parse();
424	        }
425	        return token;
426	    }
427	
428	    public JWSHeader getHeader() throws VerificationException {
429	        parse();
430	        return jws.getHeader();
431	    }
432	
433	    public void verifySignature() throws VerificationException {
434	        if (this.verifier != null) {
435	            try {
436	                if (!verifier.verify(jws.getEncodedSignatureInput().getBytes(StandardCharsets.UTF_8), jws.getSignature())) {
437	                    throw new TokenSignatureInvalidException(token, "Invalid token signature");
438	                }
439	            } catch (Exception e) {
440	                throw new VerificationException(e);
441	            }
442	        } else {
443	            AlgorithmType algorithmType = getHeader().getAlgorithm().getType();
444	            if (null == algorithmType) {
445	                throw new VerificationException("Unknown or unsupported token algorithm");
446	            }
447	            switch (algorithmType) {
448	                case RSA:
449	                    if (publicKey == null) {
450	                        throw new VerificationException("Public key not set");
451	                    }
452	                    if (!RSAProvider.verify(jws, publicKey)) {
453	                        throw new TokenSignatureInvalidException(token, "Invalid token signature");
454	                    }
455	                    break;
456	                case ECDSA:
457	                    if (publicKey == null) {
458	                        throw new VerificationException("Public key not set");
459	                    }
460	                    if (!ECDSAProvider.verify(jws, publicKey)) {
461	                        throw new TokenSignatureInvalidException(token, "Invalid token signature");
462	                    }
463	                    break;
464	                case HMAC:
465	                    if (secretKey == null) {
466	                        throw new VerificationException("Secret key not set");
467	                    }
468	                    if (!HMACProvider.verify(jws, secretKey)) {
469	                        throw new TokenSignatureInvalidException(token, "Invalid token signature");
470	                    }
471	                    break;
472	                default:
473	                    throw new VerificationException("Unknown or unsupported token algorithm");
474	            }
475	        }
476	    }
477	
478	    public TokenVerifier<T> verify() throws VerificationException {
479	        if (getToken() == null) {
480	            parse();
481	        }
482	        if (jws != null) {
483	            verifySignature();
484	        }
485	
486	        for (Predicate<? super T> check : checks) {
487	            if (! check.test(getToken())) {
488	                throw new VerificationException("JWT check failed for check " + check);
489	            }
490	        }
491	
492	        return this;
493	    }
494	
495	    /**
496	     * Creates an optional predicate from a predicate that will proceed with check but always pass.
497	     * @param <T>
498	     * @param mandatoryPredicate
499	     * @return
500	     */
501	    public static <T extends JsonWebToken> Predicate<T> optional(final Predicate<T> mandatoryPredicate) {
502	        return new Predicate<T>() {
503	            @Override
504	            public boolean test(T t) throws VerificationException {
505	                try {
506	                    if (! mandatoryPredicate.test(t)) {
507	                        LOG.finer("[optional] predicate failed: " + mandatoryPredicate);
508	                    }
509	
510	                    return true;
511	                } catch (VerificationException ex) {
512	                    LOG.log(Level.FINER, "[optional] predicate " + mandatoryPredicate + " failed.", ex);
513	                    return true;
514	                }
515	            }
516	        };
517	    }
518	
519	    /**
520	     * Creates a predicate that will proceed with checks of the given predicates
521	     * and will pass if and only if at least one of the given predicates passes.
522	     * @param <T>
523	     * @param predicates
524	     * @return
525	     */
526	    @SafeVarargs
527	    public static <T extends JsonWebToken> Predicate<T> alternative(final Predicate<? super T>... predicates) {
528	        return new Predicate<T>() {
529	            @Override
530	            public boolean test(T t) {
531	                for (Predicate<? super T> predicate : predicates) {
532	                    try {
533	                        if (predicate.test(t)) {
534	                            return true;
535	                        }
536	
537	                        LOG.finer("[alternative] predicate failed: " + predicate);
538	                    } catch (VerificationException ex) {
539	                        LOG.log(Level.FINER, "[alternative] predicate " + predicate + " failed.", ex);
540	                    }
541	                }
542	
543	                return false;
544	            }
545	        };
546	    }
547	}
