40	public class KeyUtils {
41	
42	    private static final String DEFAULT_MESSAGE_DIGEST = "SHA-256";
43	
44	    private KeyUtils() {
45	    }
46	
47	    public static SecretKey loadSecretKey(byte[] secret, String javaAlgorithmName) {
48	        return new SecretKeySpec(secret, javaAlgorithmName);
49	    }
50	
51	    public static KeyPair generateRsaKeyPair(int keysize) {
52	        try {
53	            KeyPairGenerator generator = CryptoIntegration.getProvider().getKeyPairGen("RSA"); 
54	            generator.initialize(keysize);
55	            KeyPair keyPair = generator.generateKeyPair();
56	            return keyPair;
57	        } catch (Exception e) {
58	            throw new RuntimeException(e);
59	        }
60	    }
61	
62	    public static PublicKey extractPublicKey(PrivateKey key) {
63	        if (key == null) {
64	            return null;
65	        }
66	
67	        try {
68	            RSAPrivateCrtKey rsaPrivateCrtKey = (RSAPrivateCrtKey) key;
69	            RSAPublicKeySpec publicKeySpec = new RSAPublicKeySpec(rsaPrivateCrtKey.getModulus(), rsaPrivateCrtKey.getPublicExponent());
70	            KeyFactory keyFactory = KeyFactory.getInstance("RSA");
71	            return keyFactory.generatePublic(publicKeySpec);
72	        } catch (Exception e) {
73	            throw new RuntimeException(e);
74	        }
75	    }
76	
77	    public static KeyPair generateEddsaKeyPair(String curveName) {
78	        try {
79	            KeyPairGenerator keyGen = KeyPairGenerator.getInstance(curveName);
80	            return keyGen.generateKeyPair();
81	        } catch (Exception e) {
82	            throw new RuntimeException(e);
83	        }
84	    }
85	
86	    public static KeyPair generateEcKeyPair(String keySpecName) {
87	        try {
88	            KeyPairGenerator keyGen = KeyPairGenerator.getInstance("EC");
89	            SecureRandom randomGen = new SecureRandom();
90	            ECGenParameterSpec ecSpec = new ECGenParameterSpec(keySpecName);
91	            keyGen.initialize(ecSpec, randomGen);
92	            return keyGen.generateKeyPair();
93	        } catch (Exception e) {
94	            throw new RuntimeException(e);
95	        }
96	    }
97	
98	    public static String createKeyId(Key key) {
99	        try {
100	            return Base64Url.encode(MessageDigest.getInstance(DEFAULT_MESSAGE_DIGEST).digest(key.getEncoded()));
101	        } catch (NoSuchAlgorithmException e) {
102	            throw new RuntimeException(e);
103	        }
104	    }
