21	
22	
23	/**
24	 * A utility class for handling URI template parameters. As the Java
25	 * regulare expressions package does not handle named groups, this
26	 * class attempts to simulate that functionality by using groups.
27	 *
28	 * @author Ryan J. McDonough
29	 * @author Bill Burke
30	 * @since 1.0
31	 *        Nov 8, 2006
32	 */
33	public class PathHelper
34	{
35	   public static final String URI_PARAM_NAME_REGEX = "\\w[\\w\\.-]*";
36	   public static final String URI_PARAM_REGEX_REGEX = "[^{}][^{}]*";
37	   public static final String URI_PARAM_REGEX = "\\{\\s*(" + URI_PARAM_NAME_REGEX + ")\\s*(:\\s*(" + URI_PARAM_REGEX_REGEX + "))?\\}";
38	   public static final Pattern URI_PARAM_PATTERN = Pattern.compile(URI_PARAM_REGEX);
39	
40	   /**
41	    * A regex pattern that searches for a URI template parameter in the form of {*}
42	    */
43	   public static final Pattern URI_TEMPLATE_PATTERN = Pattern.compile("(\\{([^{}]+)\\})");
44	
45	   public static final char openCurlyReplacement = 6;
46	   public static final char closeCurlyReplacement = 7;
47	
48	   public static String replaceEnclosedCurlyBraces(String str)
49	   {
50	      char[] chars = str.toCharArray();
51	      int open = 0;
52	      for (int i = 0; i < chars.length; i++)
53	      {
54	         if (chars[i] == '{')
55	         {
56	            if (open != 0) chars[i] = openCurlyReplacement;
57	            open++;
58	         }
59	         else if (chars[i] == '}')
60	         {
61	            open--;
62	            if (open != 0)
63	            {
64	               chars[i] = closeCurlyReplacement;
65	            }
66	         }
67	      }
68	      return new String(chars);
69	   }
70	
71	   public static String recoverEnclosedCurlyBraces(String str)
72	   {
73	      return str.replace(openCurlyReplacement, '{').replace(closeCurlyReplacement, '}');
74	   }
75	
76	}

