17	package org.keycloak.common.util;
18	
19	import java.net.URI;
20	import java.net.URISyntaxException;
21	import java.util.Arrays;
22	import java.util.Collection;
23	
24	/**
25	 * @author <a href="mailto:psilva@redhat.com">Pedro Igor</a>
26	 */
27	public abstract class PathMatcher<P> {
28	
29	    private static final char WILDCARD = '*';
30	    private static final String SCHEME_AUTHORITY_SEPARATOR = "://";
31	
32	    public P matches(final String targetUri) {
33	        final String normalizedUri = normalizeUri(targetUri);
34	        if (normalizedUri == null) {
35	            return null;
36	        }
37	        int patternCount = 0;
38	        int bracketsPatternCount = 0;
39	        P matchingPath = null;
40	        P matchingAnyPath = null;
41	        P matchingAnySuffixPath = null;
42	
43	        for (P entry : getPaths()) {
44	            String expectedUri = getPath(entry);
45	
46	            if (expectedUri == null || expectedUri.isEmpty()) {
47	                continue;
48	            }
49	
50	            String matchingUri = null;
51	
52	            if (exactMatch(expectedUri, normalizedUri)) {
53	                matchingUri = expectedUri;
54	            }
55	
56	            if (isTemplate(expectedUri)) {
57	                String templateUri = buildUriFromTemplate(expectedUri, normalizedUri, false);
58	
59	                if (templateUri != null) {
60	                    int length = expectedUri.split("\\/").length;
61	                    int bracketsLength = expectedUri.split("\\{").length;
62	
63	                    if (exactMatch(templateUri, normalizedUri) && (patternCount == 0 || length > patternCount || bracketsLength < bracketsPatternCount)) {
64	                        matchingUri = templateUri;
65	                        P resolved = resolvePathConfig(entry, normalizedUri);
66	
67	                        if (resolved != null) {
68	                            entry = resolved;
69	                        }
70	
71	                        patternCount = length;
72	                        bracketsPatternCount = bracketsLength;
73	                    }
74	                }
75	            }
76	
77	            if (matchingUri != null) {
78	                StringBuilder path = new StringBuilder(expectedUri);
79	                int patternIndex = path.indexOf("/" + WILDCARD);
80	
81	                if (patternIndex != -1) {
82	                    path.delete(patternIndex, path.length());
83	                }
84	
85	                patternIndex = path.indexOf("{");
86	
87	                if (patternIndex != -1) {
88	                    path.delete(patternIndex, path.length());
89	                }
90	
91	                String pathString = path.toString();
92	
93	                if ("".equals(pathString)) {
94	                    pathString = "/";
95	                }
96	
97	                if (matchingUri.equals(normalizedUri) || pathString.equals(normalizedUri)) {
98	                    if (patternCount == 0) {
99	                        return entry;
100	                    } else {
101	                        matchingPath = entry;
102	                    }
103	                }
104	
105	                if (WILDCARD == expectedUri.charAt(expectedUri.length() - 1)) {
106	                    if (matchingAnyPath == null) {
107	                        matchingAnyPath = entry;
108	                    } else {
109	                        String resourcePath = getPath(matchingAnyPath);
110	
111	                        if (resourcePath.split("/").length < matchingUri.split("/").length) {
112	                            matchingAnyPath = entry;
113	                        }
114	                    }
115	                } else {
116	                    int suffixIndex = expectedUri.indexOf(WILDCARD + ".");
117	
118	                    if (suffixIndex != -1) {
119	                        String protectedSuffix = expectedUri.substring(suffixIndex + 1);
120	
121	                        if (normalizedUri.endsWith(protectedSuffix)) {
122	                            matchingAnySuffixPath = entry;
123	                        }
124	                    }
125	                }
126	            }
127	        }
128	
129	        if (matchingPath != null) {
130	            return matchingPath;
131	        }
132	
133	        if (matchingAnySuffixPath != null) {
134	            return matchingAnySuffixPath;
135	        }
136	
137	        return matchingAnyPath;
138	    }
139	
140	    protected abstract String getPath(P entry);
141	
142	    protected abstract Collection<P> getPaths();
143	
144	    private boolean exactMatch(String expectedUri, String targetUri) {
145	        if (targetUri.equals(expectedUri)) {
146	            return true;
147	        }
148	
149	        if (endsWithWildcard(expectedUri)) {
150	            String rootPath = expectedUri.substring(0, expectedUri.length() - 1);
151	
152	            if (targetUri.startsWith(rootPath)) {
153	                return true;
154	            }
155	
156	            return targetUri.equals(rootPath.substring(0, rootPath.length() - 1));
157	        }
158	
159	        String suffix = "/*.";
160	        int suffixIndex = expectedUri.indexOf(suffix);
161	
162	        if (suffixIndex != -1) {
163	            return targetUri.endsWith(expectedUri.substring(suffixIndex + suffix.length() - 1));
164	        }
165	
166	        return false;
167	    }
168	
169	    protected String buildUriFromTemplate(String template, String targetUri, boolean onlyFirstParam) {
170	        StringBuilder uri = new StringBuilder(template);
171	        String expectedUri = uri.toString();
172	        int patternStartIndex = expectedUri.indexOf("{");
173	
174	        if (expectedUri.endsWith("/*")) {
175	            expectedUri = expectedUri.substring(0, expectedUri.length() - 2);
176	        }
177	
178	        if (patternStartIndex == -1 || patternStartIndex >= targetUri.length()) {
179	            return null;
180	        }
181	
182	        if (expectedUri.split("/").length > targetUri.split("/").length) {
183	            return null;
184	        }
185	
186	        char[] expectedUriChars = expectedUri.toCharArray();
187	        char[] matchingUri = Arrays.copyOfRange(expectedUriChars, 0, patternStartIndex);
188	        int matchingUriLastIndex = matchingUri.length;
189	        String targetUriParams = targetUri.substring(patternStartIndex);
190	
191	        if (Arrays.equals(matchingUri, Arrays.copyOf(targetUri.toCharArray(), matchingUri.length))) {
192	            matchingUri = Arrays.copyOf(matchingUri, targetUri.length());
193	            int paramIndex = 0;
194	            int lastPattern = 0;
195	
196	            for (int i = patternStartIndex; i < expectedUriChars.length; i++) {
197	                if (matchingUriLastIndex >= matchingUri.length) {
198	                    break;
199	                }
200	
201	                char c = expectedUriChars[i];
202	
203	                if (c == '{' || c == '*') {
204	                    String[] params = targetUriParams.split("/");
205	
206	                    for (int k = paramIndex; k <= (c == '*' ? params.length : paramIndex); k++) {
207	                        if (k == params.length) {
208	                            break;
209	                        }
210	
211	                        int paramLength = params[k].length();
212	
213	                        if (matchingUriLastIndex + paramLength > matchingUri.length) {
214	                            return null;
215	                        }
216	                        
217	                        StringBuilder value = new StringBuilder();
218	
219	                        for (int j = 0; j < paramLength; j++) {
220	                            char valueChar = params[k].charAt(j);
221	                            value.append(valueChar);
222	                            matchingUri[matchingUriLastIndex++] = valueChar;
223	                        }
224	
225	                        if (c == '{') {
226	                            int openBraceIndex = uri.indexOf("{", lastPattern);
227	                            int closingBraceIndex = uri.indexOf("}", lastPattern);
228	                            if (openBraceIndex == -1 || closingBraceIndex == -1 || closingBraceIndex < openBraceIndex) {
229	                                return null;
230	                            }
231	                            String paramName = uri.substring(openBraceIndex + 1, closingBraceIndex);
232	                            if (paramName.indexOf('/') != -1) {
233	                                return null;
234	                            }
235	                            uri.replace(openBraceIndex, closingBraceIndex + 1, value.toString());
236	                        }
237	
238	                        if (value.length() > 0 && value.charAt(value.length() - 1) == '}') {
239	                            lastPattern = uri.indexOf(value.toString()) + value.length();
240	                        }
241	
242	                        if (c == '*' && matchingUriLastIndex < matchingUri.length) {
243	                            matchingUri[matchingUriLastIndex++] = '/';
244	                        }
245	                    }
246	
247	                    if (c == '{') {
248	                        i = expectedUri.indexOf('}', i);
249	                    }
250	
251	                    if (i == expectedUri.lastIndexOf('}') && onlyFirstParam) {
252	                        return String.valueOf(matchingUri).substring(0, matchingUriLastIndex);
253	                    }
254	                } else {
255	                    if (c == '/') {
256	                        paramIndex++;
257	                    }
258	                    matchingUri[matchingUriLastIndex++] = c;
259	                }
260	            }
261	
262	            return uri.toString();
263	        }
264	
265	        return null;
266	    }
267	
268	    public boolean endsWithWildcard(String expectedUri) {
269	        int length = expectedUri.length();
270	        return length > 0 && WILDCARD == expectedUri.charAt(length - 1);
271	    }
272	
273	    private boolean isTemplate(String uri) {
274	        return uri.indexOf("{") != -1;
275	    }
276	
277	    /**
278	     * Validates that the given URI is a well-formed path template.
279	     *
280	     * @return an error message if the URI is invalid, or {@code null} if it is valid
281	     */
282	    public static String validateTemplate(String uri) {
283	        boolean inBrace = false;
284	        boolean empty = true;
285	
286	        for (int i = 0; i < uri.length(); i++) {
287	            char c = uri.charAt(i);
288	
289	            if (c == '{') {
290	                if (inBrace) {
291	                    return "nested '{'";
292	                }
293	                inBrace = true;
294	                empty = true;
295	            } else if (c == '}') {
296	                if (!inBrace || empty) {
297	                    return "unexpected '}' or empty parameter name";
298	                }
299	                inBrace = false;
300	            } else if (inBrace) {
301	                if (c == '/') {
302	                    return "parameter name contains '/'";
303	                }
304	                empty = false;
305	            }
306	        }
307	
308	        if (inBrace) {
309	            return "missing closing '}'";
310	        }
311	
312	        int asteriskIndex = uri.indexOf('*');
313	        if (asteriskIndex != -1) {
314	            boolean validTrailing = uri.endsWith("/*") && asteriskIndex == uri.length() - 1;
315	            boolean validSuffix = asteriskIndex > 0 && uri.charAt(asteriskIndex - 1) == '/'
316	                    && asteriskIndex + 2 < uri.length() && uri.charAt(asteriskIndex + 1) == '.'
317	                    && uri.indexOf('*', asteriskIndex + 1) == -1
318	                    && uri.indexOf('/', asteriskIndex + 1) == -1;
319	            if (!validTrailing && !validSuffix) {
320	                return "wildcard '*' is only supported as trailing '/*' or as a suffix pattern '/*.ext'";
321	            }
322	        }
323	
324	        return null;
325	    }
326	
327	    protected P resolvePathConfig(P entry, String path) {
328	        return entry;
329	    }
330	
331	    protected String normalizeUri(String uri) {
332	        if (uri == null) {
333	            return null;
334	        }
335	
336	        // drop query/fragment first, before any URI parsing - a malformed query/fragment (which we discard
337	        // unconditionally anyway) must not be able to poison the scheme/authority syntax probe below and fall
338	        // through to treating the whole value - scheme included - as a plain path
339	        String withoutQueryOrFragment = stripQueryAndFragment(uri);
340	
341	        // resources can be configured with a full absolute URI (e.g. "https://my.domain/example") rather than
342	        // just a path. Detect and preserve the "scheme://authority" prefix verbatim, normalizing only the path
343	        // that follows - otherwise the double-slash collapsing below would corrupt the "//" that separates the
344	        // scheme from the authority. This is a syntax probe only: constructing a URI does not itself normalize
345	        // anything (no dot-segment resolution, no slash collapsing, no decoding of raw components), it merely
346	        // locates where the authority ends so the prefix can be sliced off by length.
347	        String prefix = "";
348	        String path = withoutQueryOrFragment;
349	        // Only a colon before the first slash can introduce a scheme, so ordinary paths skip costly URI parsing.
350	        // This also catches authority-less URIs such as "https:/api/admin", while leaving colons inside paths alone.
351	        int colon = withoutQueryOrFragment.indexOf(':');
352	        int slash = withoutQueryOrFragment.indexOf('/');
353	        if (colon > 0 && (slash == -1 || colon < slash)) {
354	            try {
355	                URI parsed = new URI(withoutQueryOrFragment.replace("{", "%7B").replace("}", "%7D"));
356	                String scheme = parsed.getScheme();
357	                if (scheme != null) {
358	                    String authority = parsed.getRawAuthority();
359	                    if (authority == null) {
360	                        // a scheme was recognized - e.g. "https:///api/admin", where the empty authority between
361	                        // the double slash and the next slash comes back as null rather than "" - so this was
362	                        // meant to be an absolute URI. Reject it outright rather than falling back to treating
363	                        // the raw, unmangled "scheme://" text as a plain path
364	                        return null;
365	                    }
366	                    // clamp to length() - the brace-encoding above can inflate the parsed authority's length
367	                    // relative to the original string (each '{'/'}' becomes 3 chars), so a hypothetical brace inside
368	                    // the authority itself (unsupported - templates are always path-only) must not overrun it
369	                    int prefixLength = Math.min(scheme.length() + SCHEME_AUTHORITY_SEPARATOR.length() + authority.length(), withoutQueryOrFragment.length());
370	                    prefix = withoutQueryOrFragment.substring(0, prefixLength);
371	                    path = withoutQueryOrFragment.substring(prefixLength);
372	                }
373	                // scheme == null: the colon did not introduce a valid scheme; treat the value as a plain path
374	            } catch (URISyntaxException e) {
375	                // a possible scheme prefix failed to parse; do not treat it as a plain path
376	                return null;
377	            }
378	        }
379	
380	        // strip matrix params — prevents bypass via /api/admin;x=1 which Servlet/JAX-RS silently ignores when routing
381	        String result = stripMatrixParams(path);
382	
383	        // collapse double slashes before URI parsing — //foo is interpreted as a URI authority, not a path
384	        while (result.contains("//")) {
385	            result = result.replace("//", "/");
386	        }
387	
388	        // resolve dot segments and decode percent-encoding — prevents bypass via /api/foo/../admin, /api/./admin,
389	        // or /api/%61dmin. On the server side the decoding is a no-op (servlet container already decodes form/query
390	        // parameters), but on the policy enforcer side getRequestURI() preserves percent-encoding so this is needed.
391	        // Full decoding is safe because resource paths are always configured as plain decoded strings.
392	        try {
393	            // percent-encode curly braces before URI parsing — Keycloak uses {param} in path templates
394	            // and new URI() rejects them as invalid characters
395	            result = result.replace("{", "%7B").replace("}", "%7D");
396	            result = new URI(result).normalize().getPath();
397	            if (result == null) {
398	                return null;
399	            }
400	        } catch (Exception e) {
401	            return null;
402	        }
403	
404	        // repeat cleanup on decoded result - %3B decodes to ; and %2F decodes to / (introducing new // when
405	        // adjacent to existing slashes or after matrix param stripping removes content between two slashes)
406	        result = stripMatrixParams(result);
407	        while (result.contains("//")) {
408	            result = result.replace("//", "/");
409	        }
410	
411	        // re-normalize after decoding to resolve any dot segments that were not visible
412	        // to the first normalize() pass.
413	        try {
414	            result = new URI(null, null, result, null, null).normalize().getPath();
415	            if (result == null) {
416	                return null;
417	            }
418	        } catch (Exception e) {
419	            return null;
420	        }
421	
422	        // URI.normalize() leaves leading parent segments unresolved. RFC 3986 section 5.2.4 removes them
423	        // even when there is no preceding segment to remove. Do this after decoding so encoded dots and slashes
424	        // are handled as well.
425	        while (result.startsWith("/../")) {
426	            result = result.substring(3);
427	        }
428	        if (result.equals("/..")) {
429	            result = "/";
430	        }
431	
432	        // strip trailing slash - prevents bypass via /api/admin/ which routes to /api/admin on the server
433	        if (result.length() > 1 && result.endsWith("/")) {
434	            result = result.substring(0, result.length() - 1);
435	        }
436	
437	        return prefix + result;
438	    }
439	
440	    // drop query/fragment entirely — the policy enforcer never sees them (getRequestURI() excludes the query),
441	    // and resource identity for URI matching should not depend on request parameters. Doing this before matrix
442	    // param stripping also prevents a ';' from swallowing a literal '?'/'#' that follows it on the same segment.
443	    private static String stripQueryAndFragment(String path) {
444	        int queryOrFragment = path.length();
445	        int questionMark = path.indexOf('?');
446	        if (questionMark != -1) {
447	            queryOrFragment = questionMark;
448	        }
449	        int hash = path.indexOf('#');
450	        if (hash != -1 && hash < queryOrFragment) {
451	            queryOrFragment = hash;
452	        }
453	        return path.substring(0, queryOrFragment);
454	    }
455	
456	    private static String stripMatrixParams(String uri) {
457	        StringBuilder sb = new StringBuilder(uri.length());
458	        boolean inMatrix = false;
459	        for (int i = 0; i < uri.length(); i++) {
460	            char c = uri.charAt(i);
461	            if (c == ';') {
462	                inMatrix = true;
463	            } else if (c == '/') {
464	                inMatrix = false;
465	                sb.append(c);
466	            } else if (!inMatrix) {
467	                sb.append(c);
468	            }
469	        }
470	        return sb.toString();
471	    }
472	}
