18	package org.keycloak.common.enums;
19	
20	import java.net.InetAddress;
21	import java.net.UnknownHostException;
22	
23	import org.keycloak.common.ClientConnection;
24	
25	/**
26	 * @author <a href="mailto:sthorger@redhat.com">Stian Thorgersen</a>
27	 */
28	public enum SslRequired {
29	
30	    ALL,
31	    EXTERNAL,
32	    NONE;
33	
34	    public boolean isRequired(ClientConnection connection) {
35	        return isRequired(connection.getRemoteAddr());
36	    }
37	
38	    public boolean isRequired(String host) {
39	        switch (this) {
40	            case ALL:
41	                return true;
42	            case NONE:
43	                return false;
44	            case EXTERNAL:
45	                // NOTE: this is sometimes using hostnames here, which require DNS resolution
46	                // It assumes that the resolution will be the same on the client side
47	                // - this will go away once EXTERNAL is no longer supported
48	                return !isLocal(host);
49	            default:
50	                return true;
51	        }
52	    }
53	
54	    private boolean isLocal(String host) {
55	        if (host == null || host.isEmpty()) {
56	            return false; // InetAddress.getByName returns localhost for these
57	        }
58	        try {
59	            InetAddress inetAddress = InetAddress.getByName(host);
60	            return inetAddress.isLoopbackAddress() || inetAddress.isSiteLocalAddress() || inetAddress.isLinkLocalAddress() || isUniqueLocal(inetAddress);
61	        } catch (UnknownHostException e) {
62	            return false;
63	        }
64	    }
65	
66	    /**
67	     * Check if the address is within IPv6 unique local address (ULA) range RFC4193.
68	     */
69	    private boolean isUniqueLocal(InetAddress address) {
70	        if (address instanceof java.net.Inet6Address) {
71	            byte[] addr = address.getAddress();
72	            // Check if address is in unique local range fc00::/7
73	            return ((byte) (addr[0] & 0b11111110)) == (byte) 0xFC;
74	        }
75	
76	        return false;
77	    }
78	
79	}
