                    && uri.indexOf('*', asteriskIndex + 1) == -1
                    && uri.indexOf('/', asteriskIndex + 1) == -1;
            if (!validTrailing && !validSuffix) {
                return "wildcard '*' is only supported as trailing '/*' or as a suffix pattern '/*.ext'";
